/**
 * Cloud Firestore REST API Client for Cloudflare Workers Free.
 * Authenticates securely via Google Service Account (OAuth 2.0 JWT assertion).
 * Zero external dependencies. Uses standard Web Crypto API.
 */

export interface GoogleServiceAccount {
  client_email: string;
  private_key: string;
  project_id: string;
}

export interface PushTokenRecord {
  docId: string;
  token: string;
  collection: 'expo_push_tokens' | 'fcm_tokens';
}

/**
 * Strictly validates that a string matches the format of an Expo Push Token
 * generated by `Notifications.getExpoPushTokenAsync` in this application.
 *
 * Valid formats:
 * - `ExponentPushToken[xxxxxxxxxxxxxxxxxxxxxx]`
 * - `ExpoPushToken[xxxxxxxxxxxxxxxxxxxxxx]`
 *
 * Rejects native FCM registration tokens, arbitrary UUIDs, and malformed strings.
 */
export function isExpoPushToken(token: unknown): token is string {
  if (typeof token !== 'string') return false;
  const trimmed = token.trim();
  const expoTokenPattern = /^(ExponentPushToken|ExpoPushToken)\[[a-zA-Z0-9_\-+=/]{10,128}\]$/;
  return expoTokenPattern.test(trimmed);
}

export interface PendingReceiptRecord {
  ticketId: string;
  recipientUid: string;
  token: string;
  collection: 'expo_push_tokens' | 'fcm_tokens';
  docId: string;
  createdAt: number;
}


// In-memory OAuth2 token cache
let cachedAccessToken: string | null = null;
let tokenExpiresAt = 0;
let cachedPrivateKey: CryptoKey | null = null;
let cachedClientEmail = '';

function base64UrlEncode(bytes: Uint8Array): string {
  let binary = '';
  for (let i = 0; i < bytes.byteLength; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary)
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/, '');
}

function pemToBinary(pem: string): Uint8Array {
  const cleanPem = pem
    .replace(/-----BEGIN (?:RSA )?PRIVATE KEY-----/, '')
    .replace(/-----END (?:RSA )?PRIVATE KEY-----/, '')
    .replace(/\s+/g, '');

  const binary = atob(cleanPem);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}

/**
 * Obtains an OAuth 2.0 access token for Google Cloud Datastore / Firestore.
 */
async function getFirestoreAccessToken(serviceAccount: GoogleServiceAccount): Promise<string> {
  const now = Date.now();
  // Return cached token if valid for at least 5 more minutes
  if (cachedAccessToken && now < tokenExpiresAt - 300000) {
    return cachedAccessToken;
  }

  // Import private key once
  if (!cachedPrivateKey || cachedClientEmail !== serviceAccount.client_email) {
    const keyBytes = pemToBinary(serviceAccount.private_key);
    cachedPrivateKey = await crypto.subtle.importKey(
      'pkcs8',
      keyBytes as unknown as BufferSource,
      {
        name: 'RSASSA-PKCS1-v1_5',
        hash: 'SHA-256',
      },
      false,
      ['sign']
    );
    cachedClientEmail = serviceAccount.client_email;
  }

  const nowSeconds = Math.floor(now / 1000);
  const header = { alg: 'RS256', typ: 'JWT' };
  const payload = {
    iss: serviceAccount.client_email,
    scope: 'https://www.googleapis.com/auth/datastore',
    aud: 'https://oauth2.googleapis.com/token',
    exp: nowSeconds + 3600,
    iat: nowSeconds,
  };

  const textEncoder = new TextEncoder();
  const headerB64 = base64UrlEncode(textEncoder.encode(JSON.stringify(header)));
  const payloadB64 = base64UrlEncode(textEncoder.encode(JSON.stringify(payload)));
  const dataToSign = textEncoder.encode(`${headerB64}.${payloadB64}`);

  const signatureBuffer = await crypto.subtle.sign('RSASSA-PKCS1-v1_5', cachedPrivateKey, dataToSign);
  const signatureB64 = base64UrlEncode(new Uint8Array(signatureBuffer));
  const assertion = `${headerB64}.${payloadB64}.${signatureB64}`;

  // Exchange JWT for access token
  const tokenRes = await fetch('https://oauth2.googleapis.com/token', {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: `grant_type=urn:ietf:params:oauth:grant-type:jwt-bearer&assertion=${assertion}`,
  });

  if (!tokenRes.ok) {
    const errText = await tokenRes.text();
    throw new Error(`Failed to obtain Google access token: ${tokenRes.status} ${errText}`);
  }

  interface TokenResult {
    access_token: string;
    expires_in: number;
  }
  const tokenData = (await tokenRes.json()) as TokenResult;

  cachedAccessToken = tokenData.access_token;
  tokenExpiresAt = now + tokenData.expires_in * 1000;

  return cachedAccessToken;
}

/**
 * Cloud Firestore REST API Client.
 */
export class FirestoreClient {
  private serviceAccount: GoogleServiceAccount;
  private baseUrl: string;

  constructor(serviceAccount: GoogleServiceAccount) {
    this.serviceAccount = serviceAccount;
    const projectId = serviceAccount.project_id;
    this.baseUrl = `https://firestore.googleapis.com/v1/projects/${projectId}/databases/(default)/documents`;
  }

  private async getAuthHeader(): Promise<{ Authorization: string }> {
    const token = await getFirestoreAccessToken(this.serviceAccount);
    return { Authorization: `Bearer ${token}` };
  }

  /**
   * Verifies that senderUid and recipientUid are accepted mutual friends.
   */
  /**
   * Verifies that senderUid and recipientUid are accepted mutual friends.
   */
  async verifyMutualFriendship(senderUid: string, recipientUid: string): Promise<boolean> {
    const authHeaders = await this.getAuthHeader();
    const encodedRecipient = encodeURIComponent(recipientUid);
    const encodedSender = encodeURIComponent(senderUid);

    // 1. Check users/{recipientUid}/friends/{senderUid}
    const friendUrl = `${this.baseUrl}/users/${encodedRecipient}/friends/${encodedSender}`;
    const friendRes = await fetch(friendUrl, { headers: authHeaders });

    if (friendRes.ok) {
      return true;
    }

    // 2. Check friend_requests/{senderUid}_{recipientUid} or reverse
    const req1Url = `${this.baseUrl}/friend_requests/${encodedSender}_${encodedRecipient}`;
    const req1Res = await fetch(req1Url, { headers: authHeaders });
    if (req1Res.ok) {
      const data = (await req1Res.json()) as { fields?: { status?: { stringValue?: string } } };
      if (data.fields?.status?.stringValue === 'accepted') {
        return true;
      }
    }

    const req2Url = `${this.baseUrl}/friend_requests/${encodedRecipient}_${encodedSender}`;
    const req2Res = await fetch(req2Url, { headers: authHeaders });
    if (req2Res.ok) {
      const data = (await req2Res.json()) as { fields?: { status?: { stringValue?: string } } };
      if (data.fields?.status?.stringValue === 'accepted') {
        return true;
      }
    }

    return false;
  }

  /**
   * Retrieves the recipient-assigned nickname for a sender from users/{recipientUid}/nicknames/{senderUid}.
   * Returns trimmed nickname string if found and non-empty, or null if not found or on error.
   */
  async getRecipientNickname(recipientUid: string, senderUid: string): Promise<string | null> {
    try {
      const authHeaders = await this.getAuthHeader();
      const encodedRecipient = encodeURIComponent(recipientUid);
      const encodedSender = encodeURIComponent(senderUid);
      const url = `${this.baseUrl}/users/${encodedRecipient}/nicknames/${encodedSender}`;

      const res = await fetch(url, { headers: authHeaders });
      if (!res.ok) {
        return null;
      }

      interface NicknameDocResponse {
        fields?: {
          nickname?: { stringValue?: string };
        };
      }

      const data = (await res.json()) as NicknameDocResponse;
      const nick = data.fields?.nickname?.stringValue;
      return nick && typeof nick === 'string' && nick.trim() ? nick.trim().slice(0, 30) : null;
    } catch (err) {
      console.warn(`[Firestore] Failed to read nickname for ${senderUid} from ${recipientUid}:`, err);
      return null;
    }
  }

  /**
   * Writes the NearU event document into users/{recipientUid}/nearu_events/{eventId}.
   * Uses Firestore's atomic document creation: if a document with eventId already exists,
   * Firestore returns HTTP 409 Conflict (ALREADY_EXISTS), providing an atomic global deduplication guarantee.
   */
  async createNearuEventDoc(
    recipientUid: string,
    eventId: string,
    event: {
      fromUid: string;
      fromName: string;
      message: string;
      type: string;
    }
  ): Promise<{ created: boolean; alreadyExists: boolean }> {
    const authHeaders = await this.getAuthHeader();
    const encodedRecipient = encodeURIComponent(recipientUid);
    const encodedEventId = encodeURIComponent(eventId);
    const url = `${this.baseUrl}/users/${encodedRecipient}/nearu_events?documentId=${encodedEventId}`;

    const body = {
      fields: {
        fromUid: { stringValue: event.fromUid },
        fromName: { stringValue: event.fromName || 'Friend' },
        toUid: { stringValue: recipientUid },
        message: { stringValue: event.message },
        type: { stringValue: event.type },
        timestamp: { timestampValue: new Date().toISOString() },
      },
    };

    const res = await fetch(url, {
      method: 'POST',
      headers: {
        ...authHeaders,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(body),
    });

    if (res.status === 409) {
      // 409 Conflict: Document already exists (atomic duplicate prevention)
      return { created: false, alreadyExists: true };
    }

    if (!res.ok) {
      const errText = await res.text();
      console.warn(`[Firestore] Event doc write warning: ${res.status} ${errText}`);
      return { created: false, alreadyExists: false };
    }

    return { created: true, alreadyExists: false };
  }

  /**
   * Fetches recipient's registered Expo push tokens.
   * Scans both expo_push_tokens and fcm_tokens subcollections, keeping tokens private from other clients.
   * Only returns valid Expo push tokens, discarding native FCM or malformed tokens.
   */
  async getRecipientPushTokens(recipientUid: string): Promise<PushTokenRecord[]> {
    const authHeaders = await this.getAuthHeader();
    const encodedRecipient = encodeURIComponent(recipientUid);
    const tokens: PushTokenRecord[] = [];

    // Helper to query a subcollection
    const fetchSubcollection = async (sub: 'expo_push_tokens' | 'fcm_tokens') => {
      const url = `${this.baseUrl}/users/${encodedRecipient}/${encodeURIComponent(sub)}`;
      const res = await fetch(url, { headers: authHeaders });
      if (!res.ok) return;

      interface FirestoreListResponse {
        documents?: {
          name: string;
          fields?: {
            token?: { stringValue?: string };
            type?: { stringValue?: string };
          };
        }[];
      }

      const data = (await res.json()) as FirestoreListResponse;
      if (Array.isArray(data.documents)) {
        for (const doc of data.documents) {
          const rawToken = doc.fields?.token?.stringValue;
          if (rawToken && isExpoPushToken(rawToken)) {
            const parts = doc.name.split('/');
            const docId = parts[parts.length - 1];
            tokens.push({
              docId,
              token: rawToken,
              collection: sub,
            });
          }
        }
      }
    };

    await Promise.all([
      fetchSubcollection('expo_push_tokens'),
      fetchSubcollection('fcm_tokens'),
    ]);

    // Deduplicate by token string
    const seen = new Set<string>();
    return tokens.filter((t) => {
      if (seen.has(t.token)) return false;
      seen.add(t.token);
      return true;
    });
  }

  /**
   * Cleans up invalid / unregistered tokens from Firestore.
   */
  async deletePushToken(recipientUid: string, tokenRecord: PushTokenRecord): Promise<void> {
    const authHeaders = await this.getAuthHeader();
    const encodedRecipient = encodeURIComponent(recipientUid);
    const encodedSub = encodeURIComponent(tokenRecord.collection);
    const encodedDocId = encodeURIComponent(tokenRecord.docId);
    const url = `${this.baseUrl}/users/${encodedRecipient}/${encodedSub}/${encodedDocId}`;
    await fetch(url, {
      method: 'DELETE',
      headers: authHeaders,
    }).catch(() => {});
  }

  /**
   * Saves a pending push notification receipt record to Firestore so it can be verified later.
   */
  async savePendingReceipt(receipt: PendingReceiptRecord): Promise<void> {
    const authHeaders = await this.getAuthHeader();
    const encodedTicketId = encodeURIComponent(receipt.ticketId);
    const url = `${this.baseUrl}/pending_receipts?documentId=${encodedTicketId}`;

    const body = {
      fields: {
        ticketId: { stringValue: receipt.ticketId },
        recipientUid: { stringValue: receipt.recipientUid },
        token: { stringValue: receipt.token },
        collection: { stringValue: receipt.collection },
        docId: { stringValue: receipt.docId },
        createdAt: { integerValue: String(receipt.createdAt) },
      },
    };

    await fetch(url, {
      method: 'POST',
      headers: {
        ...authHeaders,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(body),
    }).catch(() => {});
  }

  /**
   * Retrieves pending receipts eligible for checking (created at least olderThanMs ago).
   * Also cleans up expired receipts (older than 24 hours, since Expo purges receipts after 24h).
   */
  async getPendingReceipts(olderThanMs: number, maxLimit = 100): Promise<PendingReceiptRecord[]> {
    const authHeaders = await this.getAuthHeader();
    const url = `${this.baseUrl}/pending_receipts?pageSize=${maxLimit}`;
    const res = await fetch(url, { headers: authHeaders });
    if (!res.ok) return [];

    interface PendingReceiptsResponse {
      documents?: {
        name: string;
        fields?: {
          ticketId?: { stringValue?: string };
          recipientUid?: { stringValue?: string };
          token?: { stringValue?: string };
          collection?: { stringValue?: string };
          docId?: { stringValue?: string };
          createdAt?: { integerValue?: string };
        };
      }[];
    }

    const data = (await res.json()) as PendingReceiptsResponse;
    if (!Array.isArray(data.documents)) return [];

    const now = Date.now();
    const eligible: PendingReceiptRecord[] = [];
    const EXPO_RECEIPT_MAX_LIFETIME_MS = 24 * 60 * 60 * 1000; // 24 hours

    for (const doc of data.documents) {
      const f = doc.fields;
      const ticketId = f?.ticketId?.stringValue;
      const recipientUid = f?.recipientUid?.stringValue;
      const token = f?.token?.stringValue;
      const collection = f?.collection?.stringValue as 'expo_push_tokens' | 'fcm_tokens';
      const docId = f?.docId?.stringValue;
      const createdAt = Number(f?.createdAt?.integerValue || 0);

      if (!ticketId || !recipientUid || !token || !collection || !docId) {
        continue;
      }

      const age = now - createdAt;

      // Purge receipts older than 24 hours (expired from Expo's service)
      if (age > EXPO_RECEIPT_MAX_LIFETIME_MS) {
        await this.deletePendingReceipt(ticketId);
        continue;
      }

      // Only query receipts after the specified delay (e.g. 15 minutes)
      if (age >= olderThanMs) {
        eligible.push({
          ticketId,
          recipientUid,
          token,
          collection,
          docId,
          createdAt,
        });
      }
    }

    return eligible;
  }

  /**
   * Deletes a processed pending receipt record from Firestore.
   */
  async deletePendingReceipt(ticketId: string): Promise<void> {
    const authHeaders = await this.getAuthHeader();
    const encodedTicketId = encodeURIComponent(ticketId);
    const url = `${this.baseUrl}/pending_receipts/${encodedTicketId}`;
    await fetch(url, {
      method: 'DELETE',
      headers: authHeaders,
    }).catch(() => {});
  }
}

